 "content": "def transform(grid):
    """Combine four vertically stacked 3-row layers, taking first nonzero by layer."""
    if len(grid) % 4 != 0:
        raise ValueError("expected four equal-height stacked layers")
    h, w = len(grid) // 4, len(grid[0])
    if any(len(row) != w for row in grid):
        raise ValueError("ragged grid")
    return [[next((grid[k * h + r][c] for k in range(4) if grid[k * h + r][c] != 0), 0)
